// The per-frame world update (SW vtable slot 7): runs callbacks, updates the objects (UpdateSwObjects), lights, sound
// and the camera. Called once per game frame by the main loop.
void SW::Update()
{
    SWVIEW *p = (SWVIEW *)this;
    ProcessSwCallbacks(p);
    UpdateSwBusyList(p);
    if (D_002DDED0.dt <= 0.0f) {
        UpdateSwObjects(p);
    } else {
        LOPOCTL *pl;
        int i;
        DLI dli, dli2;
        void *pv;
        for (pl = p->plopoctlFirst; pl; pl = pl->pnext)
            UpdatePoctl(pl);
        ExpireSwZapRecords(p);
        p->pientry = &i;
        for (i = 0; i < p->centry; i++) {
            SWENTRY *pe = &p->aentry[i];
            if (pe->grf & 2) {
                BASICV *po = pe->po;
                ((void (*)(void *))po->vt[16].pfn)((char *)po + po->vt[16].d);
            }
        }
        p->pientry = 0;
        UpdateSwGuardOverride(p);
        InitDli(&dli, &p->dlAsega);
        while ((pv = PvNextDli(&dli)) != 0)
            UpdateAsega(pv);
        InitDli(&dli2, &p->dl3FFC);
        while ((pv = PvNextDli(&dli2)) != 0)
            func_00156728(pv);
        ProcessSwCallbacks(p);
        SolveSw(p);
        func_001BE1E8();
        UpdateShaders();
        ProcessSwCallbacks(p);
        D_002DD2FC = dli.m_pdliNext;
    }
    UpdateSave__FP4SAVE(D_002E65E0);
    UpdateSndmgr(D_003DD040);
    if (0.0f < D_002DDED0.dtCm)
        UpdateCmLast__FP2CM(D_002DDF40);
    UpdateSwTimerHud(p);
    CGc_UpdateRecyclable(g_gc);
}

